struct Solution;

impl Solution {
    pub fn find_max_consecutive_ones(nums: Vec<i32>) -> i32 {
        let mut max = 0;
        let mut index: usize = 0;
        let mut current = 0;
        while (index < nums.len()) {

            if (nums[index] == 0) {
                if (current > max) {
                    max = current;
                }

                current = 0;
                index += 1;
                continue;
            }

            current += 1;
            index += 1;
        }

        if current > max {
            current
        } else {
            max
        }
    }
}
